Aqui está um esqueleto robusto. Vamos focar na lógica de receber o link, chamar a API e formatar a resposta.

```javascript
require('dotenv').config();
const { Client, GatewayIntentBits } = require('discord.js');
const axios = require('axios');

const client = new Client({ 
    intents: [
        GatewayIntentBits.Guilds, 
        GatewayIntentBits.GuildMessages, 
        GatewayIntentBits.MessageContent // ESSENCIAL para ler o conteúdo das mensagens
    ] 
});

const API_URL = process.env.API_URL;

client.on('ready', () => {
    console.log(`✅ Bot conectado como ${client.user.tag}!`);
    client.user.setActivity('Analisando PDFs 📄');
});

// --- LÓGICA DO COMANDO ---
client.on('messageCreate', async message => {
    // Ignora mensagens do próprio bot e mensagens que não começam com o prefixo
    if (message.author.bot || !message.content.startsWith('!')) return;

    const args = message.content.slice(1).trim().split(/ +/);
    const command = args.shift().toLowerCase();

    // Comando principal: !analisar <link_pdf>
    if (command === 'analisar') {
        if (args.length === 0) {
            return message.reply("❌ Por favor, forneça um link do PDF. Exemplo: `!analisar https://exemplo.com/doc.pdf`");
        }

        const pdfLink = args[0];

        // 1. Resposta Imediata (Feedback)
        await message.reply(`⏳ Recebi o link: ${pdfLink}. Enviando para a API para extrair as informações. Por favor, aguarde um momento...`);

        try {
            // 2. Chamada à API
            console.log(`Chamando API com link: ${pdfLink}`);
            const response = await axios.get(API_URL, {
                params: { 
                    pdf_url: pdfLink // Ajuste este parâmetro conforme sua API espera
                }
            });

            // Assumindo que a API retorna um JSON bem estruturado (ex: {titulo: '...', resumo: '...', palavras_chave: [...]})
            const dadosExtraidos = response.data;

            // 3. Formatação Bonita e Organizada (Usando Embeds do Discord)
            const embed = {
                color: 0x0099ff, // Uma cor azul agradável
                title: "📄 Análise do Documento Concluída",
                description: `As informações solicitadas para o link fornecido foram extraídas com sucesso!`,
                fields: [
                    { name: "📚 Título do Documento", value: dadosExtraidos.titulo || "N/A", inline: true },
                    { name: "📝 Resumo", value: dadosExtraidos.resumo ? dadosExtraidos.resumo.substring(0, 1024) : "Nenhum resumo encontrado.", inline: false }, // Limita para não estourar o limite do campo
                    { name: "🏷️ Palavras-Chave", value: (dadosExtraidos.palavras_chave || []).join(', ') || "Nenhuma palavra-chave listada.", inline: true },
                    { name: "🔢 Total de Páginas", value: dadosExtraidos.paginas || "Não disponível", inline: true }
                ],
                timestamp: new Date(), // Adiciona um carimbo de data/hora
                footer: { text: "Bot de Análise PDF | Integrado com sua API" }
            };

            // 4. Envio para o Usuário
            await message.channel.send({ embeds: [embed] });

        } catch (error) {
            console.error("Erro ao processar a requisição:", error.message);

            // Tratamento de erro amigável
            let errorMessage = "❌ Ocorreu um erro ao contatar a API ou processar o link.";
            if (error.response) {
                errorMessage += ` Status da API: ${error.response.status}. Detalhe: ${JSON.stringify(error.response.data)}`;
            } else if (error.code === 'ECONNREFUSED') {
                errorMessage += " Verifique se a URL da API está correta e se ela está online.";
            }

            await message.reply(errorMessage);
        }
    }
});

// Login do Bot
client.login(process.env.DISCORD_TOKEN);
```

### ✨ Dicas para "Comandos Bonitos e Organizados"

1. **Usar Embeds (Como feito acima):** Em vez de enviar texto simples (`"O título é X, o resumo é Y..."`), use `Embeds`. Eles permitem cores, títulos, descrições, campos estruturados e timestamps, tornando a saída profissional.
2. **Prefixos Claros:** Use um prefixo simples (ex: `!`) e comandos verbosos (ex: `!analisar`).
3. **Feedback Imediato:** **Nunca deixe o usuário esperando em silêncio.** Quando o comando for chamado, envie uma mensagem de "Processando..." imediatamente. Isso gerencia a expectativa do usuário.
4. **Tratamento de Erros:** Mensagens de erro amigáveis são cruciais. Se a API falhar, diga *o que* falhou e *como* o usuário pode tentar corrigir, em vez de apenas mostrar um erro técnico.

